const STORE_KEY = 'greenfarm-mvp-v2';
const today = new Date();
const isoDay = (offset=0) => { const d=new Date(today); d.setDate(d.getDate()+offset); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const dateLabel = value => value ? new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(`${value}T12:00:00`)).replace('.','') : 'Não definida';
const initialState = {requests:[],processes:[],currentPage:'inicio',tab:'Ativas'};
let state; try{state=JSON.parse(localStorage.getItem(STORE_KEY))||structuredClone(initialState)}catch{state=structuredClone(initialState)}
if(!state.requests?.length) state=structuredClone(initialState);
let persistQueue=Promise.resolve();
const save=()=>{localStorage.setItem(STORE_KEY,JSON.stringify(state));if(location.protocol==='http:'||location.protocol==='https:'){const snapshot=JSON.stringify(state);persistQueue=persistQueue.catch(()=>{}).then(()=>fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot})).catch(()=>toast('Não foi possível salvar no servidor. Verifique a conexão.',true));}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activeStages=['Em análise','Aprovadas','Programadas','Em contratação','Aguardando entrega'];
const pageTitles={inicio:'Visão geral',requisicoes:'Requisições',programacao:'Programação',processos:'Processos',recebimentos:'Recebimentos',indicadores:'Indicadores',historico:'Histórico',cadastros:'Cadastros'};
const stageClass=s=>s==='Concluídas'?'badge-ok':s==='Em análise'?'badge-pending':'badge-stage';
const priorityClass=k=>k==='immediate'?'priority-immediate':k==='advance'?'priority-advance':k==='planned'?'priority-planned':'priority-unknown';
const badge=(text,cls)=>`<span class="badge ${cls}">${esc(text)}</span>`;
const tags=r=>`<div class="tag-row">${r.abc?badge(`ABC ${r.abc}`,`abc-${r.abc.toLowerCase()}`):badge('ABC não classificado','badge-stage')}${r.xyz?badge(`XYZ ${r.xyz}`,`xyz-${r.xyz.toLowerCase()}`):badge('XYZ não classificado','badge-stage')}</div>`;
const remaining=r=>Math.max(0,(Number(r.approved)||0)-(Number(r.accepted)||0));
const byId=id=>state.requests.find(r=>r.id===id);
const currentPage=()=>state.currentPage||'inicio';

function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function miniCard(r){return `<article class="mini-ticket" data-open="${r.id}"><div class="ticket-number">${r.id}</div><div class="ticket-name">${esc(r.item)}</div><div class="ticket-foot"><span>${r.approved||r.qty} un.</span><span class="priority-pill ${priorityClass(r.priorityKey)}">${esc(r.priority)}</span></div></article>`}
function dashboard(){const reqs=state.requests,active=reqs.filter(r=>activeStages.includes(r.stage)),pending=reqs.filter(r=>r.pending),soon=reqs.filter(r=>r.stage==='Aguardando entrega'&&remaining(r)>0);
 const cols=['Em análise','Aprovadas','Programadas','Em contratação'];
 return `${heading(new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(today).toUpperCase(),'Olá, equipe <span aria-hidden="true">✳</span>','Aqui está o panorama das demandas da Saúde de Ceres.',`<button class="primary-button" data-action="new-request"><span class="plus">+</span> Nova requisição</button>`)}
 <div class="dashboard-grid"><div><section class="overview-hero"><div class="hero-content"><div class="hero-kicker"><i class="live-dot"></i> PAINEL DE ACOMPANHAMENTO</div><h2>Decisões claras. Cuidado contínuo.</h2><p>As informações certas para manter cada demanda em movimento.</p><button class="hero-button" data-go="programacao">Acompanhar programação <span>↗</span></button></div><div class="hero-orbit"></div><img class="hero-mark" src="Logo GreenFarm.png" alt="" /></section>
 <div class="metric-grid"><div class="metric-card"><div class="metric-top"><span>Demandas ativas</span><span class="metric-symbol">▤</span></div><div class="metric-number">${active.length}</div><div class="metric-bottom"><span class="trend">${reqs.filter(r=>r.stage==='Em análise').length} novas</span> em análise</div></div><div class="metric-card"><div class="metric-top"><span>Requerem atenção</span><span class="metric-symbol">◉</span></div><div class="metric-number">${pending.length+reqs.filter(r=>r.priorityKey==='immediate').length}</div><div class="metric-bottom">${pending.length} com pendência aberta</div></div><div class="metric-card"><div class="metric-top"><span>Em recebimento</span><span class="metric-symbol">⇣</span></div><div class="metric-number">${soon.length}</div><div class="metric-bottom">${soon.reduce((n,r)=>n+remaining(r),0)} unidades pendentes</div></div><div class="metric-card"><div class="metric-top"><span>Concluídas no mês</span><span class="metric-symbol">✓</span></div><div class="metric-number">${reqs.filter(r=>r.stage==='Concluídas').length}</div><div class="metric-bottom">Dados demonstrativos</div></div></div>
 <section class="panel"><div class="panel-heading"><div><h3>Fila de acompanhamento</h3><p>Uma visão rápida do que está em andamento</p></div><button class="text-link" data-go="requisicoes">Ver todas as demandas →</button></div><div class="mini-board">${cols.map(c=>{const list=reqs.filter(r=>r.stage===c);return `<div class="mini-column"><div class="mini-column-head"><span>${c}</span><b>${list.length}</b></div>${list.slice(0,2).map(miniCard).join('')||'<div class="section-caption">Sem demandas</div>'}</div>`}).join('')}</div></section></div>
 <div><section class="panel"><div class="panel-heading"><div><h3>Próximas ações</h3><p>O que precisa de atenção da equipe</p></div><button class="text-link" data-go="historico">Ver histórico</button></div><div class="action-list">${[...pending,...reqs.filter(r=>r.priorityKey==='immediate'&&!r.pending),...soon].slice(0,4).map((r,i)=>`<div class="action-row" data-open="${r.id}"><span class="action-mark ${r.pending?'mark-amber':i===0?'mark-red':'mark-blue'}">${r.pending?'!':i===0?'↗':'⇣'}</span><span class="action-copy"><strong>${esc(r.pending||r.item)}</strong><small>${r.id} · ${esc(r.unit)}</small></span><span class="action-time"><strong>${r.pending?'Pendente':dateLabel(r.due)}</strong>${r.pending?'Revisar':'Previsão'}</span></div>`).join('')||'<div class="empty-state">Nenhuma ação pendente.</div>'}</div></section>
 <section class="panel" style="margin-top:13px"><div class="panel-heading"><div><h3>Leitura de prioridade</h3><p>Com base nas decisões registradas</p></div><span class="badge badge-stage">Neste momento</span></div><div class="action-list"><div class="action-row"><span class="action-mark mark-red">1</span><span class="action-copy"><strong>Revisão imediata</strong><small>Falta ou risco com impacto validado</small></span><span class="action-time"><strong>${reqs.filter(r=>r.priorityKey==='immediate').length}</strong>casos</span></div><div class="action-row"><span class="action-mark mark-amber">2</span><span class="action-copy"><strong>Antecipação necessária</strong><small>Horizonte próximo ao prazo previsto</small></span><span class="action-time"><strong>${reqs.filter(r=>r.priorityKey==='advance').length}</strong>casos</span></div><div class="action-row"><span class="action-mark mark-blue">3</span><span class="action-copy"><strong>Planejada</strong><small>Dentro do horizonte de atendimento</small></span><span class="action-time"><strong>${reqs.filter(r=>r.priorityKey==='planned').length}</strong>casos</span></div></div><div class="page-note">A prioridade é registrada pela equipe responsável; a GreenFarm organiza as evidências e não decide automaticamente.</div></section></div></div>`}

function requestCard(r){return `<article class="request-card" draggable="true" data-card="${r.id}" data-open="${r.id}"><div class="request-card-head"><span class="ticket-number">${r.id}</span>${r.pending?'<span class="badge badge-pending">Pendência</span>':''}</div><h4>${esc(r.item)}</h4><div class="unit-name">${esc(r.unit)}</div>${tags(r)}<div class="request-card-footer"><span>${r.approved||r.qty} un. · ${esc(r.owner||'Sem responsável')}</span><span>${dateLabel(r.due)}</span></div><div class="priority-pill ${priorityClass(r.priorityKey)}" style="display:inline-block;margin-top:8px">${esc(r.priority)}</div></article>`}
function board(){const columns=[['Em análise','Em análise'],['Aprovadas','Aprovadas'],['Programadas','Programadas'],['Em contratação','Em contratação'],['Aguardando entrega','Aguardando entrega']];return `${heading('GESTÃO DE DEMANDAS','Programação','Acompanhe cada demanda pela etapa atual. A prioridade e as pendências permanecem independentes.',`<button class="primary-button" data-action="new-request"><span class="plus">+</span> Nova requisição</button>`)}<div class="board-toolbar"><div class="filter-row"><button class="filter-button active" data-filter="all">Todas as unidades</button><button class="filter-button" data-filter="priority">Prioridade imediata</button><button class="filter-button" data-filter="pending">Com pendência</button></div><div class="section-caption">${state.requests.filter(r=>activeStages.includes(r.stage)).length} demandas em andamento</div></div><div class="board-scroll"><div class="full-board">${columns.map(([name,stage])=>{const list=state.requests.filter(r=>r.stage===stage&&r.stage!=='Concluídas');return `<section class="board-column" data-column="${stage}"><div class="column-head"><span>${name}</span><span class="column-count">${list.length}</span></div>${list.map(requestCard).join('')||'<div class="section-caption">Arraste ou programe uma demanda aprovada</div>'}</section>`}).join('')}</div></div><div class="page-note">Arrastar um cartão abre uma confirmação de mudança de etapa. A mudança só será gravada após validação e confirmação. Use Enter ou abra o cartão para acessar as ações por teclado.</div>`}

function requestTable(list){if(!list.length)return `<div class="empty-state"><div style="font-size:24px">⌕</div><strong>Nenhuma requisição encontrada</strong>Revise os filtros ou crie uma nova demanda.<br><button class="secondary-button" style="margin-top:12px" data-action="new-request">Nova requisição</button></div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>NÚMERO</th><th>ITEM / UNIDADE</th><th>ETAPA</th><th>PRIORIDADE</th><th>PREVISÃO</th><th>SALDO</th><th></th></tr></thead><tbody>${list.map(r=>`<tr data-open="${r.id}"><td class="table-id">${r.id}</td><td><span class="table-item">${esc(r.item)}</span><br><span style="font-size:8px;color:#9aa4af">${esc(r.unit)}</span></td><td>${badge(r.stage,stageClass(r.stage))}${r.pending?`<br>${badge('Pendência','badge-pending')}`:''}</td><td><span class="priority-pill ${priorityClass(r.priorityKey)}">${esc(r.priority)}</span></td><td>${dateLabel(r.due)}</td><td>${remaining(r)} un.</td><td style="font-size:16px;color:#9aa5b2">›</td></tr>`).join('')}</tbody></table></div>`}
function requestsPage(){const tab=state.tab||'Ativas';const tabs=['Ativas','Rascunhos','Concluídas','Indeferidas','Canceladas'];let list=state.requests;if(tab==='Concluídas')list=list.filter(r=>r.stage==='Concluídas');else if(tab!=='Rascunhos')list=list.filter(r=>r.stage!=='Concluídas');return `${heading('GESTÃO DE DEMANDAS','Requisições','Consulte as solicitações da rede e acompanhe cada decisão.',`<button class="primary-button" data-action="new-request"><span class="plus">+</span> Nova requisição</button>`)}<div class="segmented">${tabs.map(t=>`<button class="segment ${tab===t?'active':''}" data-tab="${t}">${t}${t==='Ativas'?` (${state.requests.filter(r=>r.stage!=='Concluídas').length})`:''}</button>`).join('')}</div><div class="table-toolbar"><input class="input-like" id="request-search" type="search" placeholder="Buscar por número ou item" /><div class="table-filters"><select class="select-like" id="priority-filter"><option value="">Todas as prioridades</option><option>Revisão imediata</option><option>Antecipação necessária</option><option>Planejada</option></select><select class="select-like" id="stage-filter"><option value="">Todas as etapas</option>${activeStages.map(s=>`<option>${s}</option>`).join('')}</select><button class="secondary-button" data-action="export">↓ Exportar</button></div></div><div id="request-table">${requestTable(list)}</div>`}

function processPage(){return `${heading('ACOMPANHAMENTO','Processos de compra','A GreenFarm acompanha as referências oficiais e seus vínculos com as demandas.',`<button class="primary-button" data-action="new-process"><span class="plus">+</span> Cadastrar processo</button>`)}<div class="table-toolbar"><input class="input-like" id="process-search" placeholder="Buscar processo ou responsável"/><span class="section-caption">${state.processes.length} processos cadastrados</span></div><div class="process-grid">${state.processes.map(p=>`<article class="process-card" data-process="${p.id}"><div class="process-number">${p.id}</div><h3>${esc(p.org)}</h3><p>${esc(p.owner)} · ${esc(p.stage)}</p><div class="process-stats"><span>${state.requests.filter(r=>r.process===p.id).length} requisições vinculadas</span><span>Ver detalhes →</span></div></article>`).join('')}</div><div class="page-note">O cadastro registra a referência do processo oficial. A GreenFarm não executa atos de contratação.</div>`}
function receivesPage(){const list=state.requests.filter(r=>r.stage==='Aguardando entrega'&&remaining(r)>0);return `${heading('ACOMPANHAMENTO','Recebimentos','Registre conferências parciais e acompanhe o saldo que falta atender.',`<button class="primary-button" data-action="receive"><span>＋</span> Registrar recebimento</button>`)}<div class="panel-heading"><div><h3>Fila de recebimento</h3><p>${list.length} demandas aguardam entrega total ou complementar</p></div><span class="badge badge-stage">${list.reduce((n,r)=>n+remaining(r),0)} unidades pendentes</span></div><div class="receive-list">${list.map(r=>`<div class="receive-row"><span class="receive-icon">⇣</span><span class="receive-info"><strong>${esc(r.item)}</strong><p>${r.id} · ${esc(r.unit)} · ${r.process||'Processo não vinculado'}</p></span><span class="receive-qty"><strong>${remaining(r)} un.</strong>de ${r.approved} aprovadas</span><button class="mini-action" data-receive="${r.id}">Conferir entrega</button></div>`).join('')||'<div class="panel empty-state"><div style="font-size:22px">✓</div><strong>Nenhum recebimento pendente</strong>As próximas entregas aparecerão aqui.</div>'}</div><div class="page-note">Quantidade rejeitada não conta como aceita. O saldo é recalculado com base na quantidade efetivamente conferida.</div>`}
function analyticsPage(){const completed=state.requests.filter(r=>r.stage==='Concluídas').length,active=state.requests.filter(r=>activeStages.includes(r.stage)).length,pending=state.requests.filter(r=>r.pending).length;const months=Array.from({length:8},(_,i)=>new Date(today.getFullYear(),today.getMonth()-7+i,1));const counts=months.map(month=>{const received=state.requests.filter(r=>r.created&&new Date(`${r.created}T12:00:00`).getFullYear()===month.getFullYear()&&new Date(`${r.created}T12:00:00`).getMonth()===month.getMonth()).length,done=state.requests.filter(r=>r.stage==='Concluídas'&&r.history?.some(h=>new Date(`${h.date}T12:00:00`).getFullYear()===month.getFullYear()&&new Date(`${h.date}T12:00:00`).getMonth()===month.getMonth())).length;return{month,received,done}}),maximum=Math.max(1,...counts.flatMap(c=>[c.received,c.done])),stats=state.requests.some(r=>r.created)?counts.map(c=>`<div class="chart-month"><div class="bar-pair"><i class="bar" style="height:${Math.max(4,c.received/maximum*85)}px"></i><i class="bar current" style="height:${Math.max(4,c.done/maximum*85)}px"></i></div><small>${new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(c.month).replace('.','')}</small></div>`).join(''):'<div class="chart-empty">Sem base para cálculo</div>';const priorities=[['Revisão imediata','immediate','#b94a4a'],['Antecipação necessária','advance','#a26821'],['Planejada','planned','#2e8465'],['A confirmar','unknown','#8491a1']].map(([label,key,color])=>({label,color,count:state.requests.filter(r=>r.priorityKey===key).length}));let step=0;const total=state.requests.length,segments=priorities.map(p=>{const start=step;step+=total?p.count/total*100:0;return`${p.color} ${start}% ${step}%`}).join(', '),donutStyle=total?`conic-gradient(${segments})`:'conic-gradient(#e4eaf0 0 100%)';return `${heading('ACOMPANHAMENTO','Indicadores','Métricas calculadas somente a partir dos registros existentes.',`<button class="secondary-button" data-action="export">↓ Exportar relatório</button>`)}<div class="analytics-grid"><section class="panel chart-panel"><div class="panel-heading"><div><h3>Entrada de demandas</h3><p>Últimos oito meses · baseado nas datas cadastradas</p></div><span class="badge badge-stage">Requisições</span></div><div class="chart-bars">${stats}</div><div class="legend"><span><i></i>Recebidas</span><span><i class="dark"></i>Concluídas</span></div></section><section class="panel chart-panel"><div class="panel-heading"><div><h3>Demandas por prioridade</h3><p>Decisões atuais registradas</p></div></div><div class="donut-wrap"><div class="donut" style="background:${donutStyle}"><div class="donut-center"><strong>${total}</strong><small>DEMANDAS</small></div></div><div class="legend-list">${priorities.map(p=>`<span class="legend-line"><i style="background:${p.color}"></i>${p.label} · ${p.count}</span>`).join('')}</div></div></section></div><div class="stat-strip"><div class="stat-tile"><small>Demandas em andamento</small><strong>${active}</strong><span>Casos ativos na fila</span></div><div class="stat-tile"><small>Pendências registradas</small><strong>${pending}</strong><span>Exigem retorno ou conferência</span></div><div class="stat-tile"><small>Concluídas</small><strong>${completed}</strong><span>Entrega integral confirmada</span></div></div><div class="page-note">Indicadores de prazo e previsibilidade requerem histórico válido. Sem base disponível, os gráficos indicam isso em vez de mostrar valores inventados.</div>`}
function historyPage(){const events=state.requests.flatMap(r=>r.history.map(h=>({...h,id:r.id,item:r.item}))).sort((a,b)=>b.date.localeCompare(a.date));return `${heading('RASTREABILIDADE','Histórico de atividades','Decisões e movimentações registradas nas requisições.',`<button class="secondary-button" data-action="export">↓ Exportar histórico</button>`)}<section class="panel"><div class="panel-heading"><div><h3>Atividade recente</h3><p>Eventos de demonstração · ordenados do mais recente</p></div><select class="select-like" id="history-filter"><option value="">Todas as demandas</option>${state.requests.map(r=>`<option value="${r.id}">${r.id}</option>`).join('')}</select></div><div class="timeline" id="timeline">${events.map(h=>`<div class="timeline-item" data-history="${h.id}"><span class="timeline-time">${dateLabel(h.date)}</span><span class="timeline-rail"><i class="timeline-dot"></i></span><span class="timeline-copy"><strong>${esc(h.text)}</strong><p>${h.id} · ${esc(h.item)} · por ${esc(h.actor)}</p></span></div>`).join('')}</div></section>`}
function catalogPage(){const items=[['MED-0001','Paracetamol 500 mg','Comprimido','A','Z'],['MED-0002','Insulina NPH 100 UI/ml','Frasco-ampola','B','Z'],['MED-0003','Amoxicilina 250 mg/5 ml','Suspensão oral','A','Y'],['MED-0004','Losartana 50 mg','Comprimido','B','X'],['MED-0005','Soro fisiológico 0,9% 500 ml','Frasco','C','Y'],['MED-0006','Omeprazol 20 mg','Cápsula','C','X']];return `${heading('CONFIGURAÇÃO','Cadastros','Itens e referências para contextualizar as requisições.',`<button class="primary-button" data-action="new-item"><span class="plus">+</span> Cadastrar item</button>`)}<div class="table-toolbar"><input class="input-like" id="catalog-search" placeholder="Buscar item ou código"/><span class="badge badge-stage">${items.length} itens demonstrativos</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>CÓDIGO</th><th>ITEM</th><th>APRESENTAÇÃO</th><th>CLASSIFICAÇÃO ABC</th><th>CRITICIDADE XYZ</th></tr></thead><tbody>${items.map(i=>`<tr><td class="table-id">${i[0]}</td><td class="table-item">${i[1]}</td><td>${i[2]}</td><td>${badge(`ABC ${i[3]}`,`abc-${i[3].toLowerCase()}`)}</td><td>${badge(`XYZ ${i[4]}`,`xyz-${i[4].toLowerCase()}`)}</td></tr>`).join('')}</tbody></table></div><div class="page-note">ABC representa participação no valor consumido. XYZ representa criticidade assistencial. As duas classes são independentes, informativas e não determinam a prioridade de compra.</div>`}

function homeGuide(){
 return `<section class="home-help-shortcut" aria-label="Ajuda da GreenFarm"><span class="home-help-mark">?</span><span class="home-help-copy"><strong>Precisa rever algum passo?</strong><small>Abra o tutorial da GreenFarm quando precisar.</small></span><button type="button" class="home-help-button" data-tutorial-open>Ver tutorial <span>↗</span></button></section><section class="tutorial-section" id="tutorial" aria-hidden="true"></section>`
}
const tutorialSteps=[
 {tab:'Requisição',hint:'Registre a demanda',title:'Comece pela necessidade da unidade',body:'Escolha o item, informe a quantidade e conte por que e quando ele será necessário. Anexe ou descreva as evidências disponíveis.',tip:'No envio, unidade, item, quantidade, data da necessidade, justificativa e impacto da falta são obrigatórios.',button:'Criar requisição',action:'new-request'},
 {tab:'Análise',hint:'Revise as informações',title:'Analise, responda e decida',body:'A equipe técnica confere os dados. A coordenação registra a quantidade aprovada e confirma a prioridade com uma justificativa.',tip:'Se faltar informação, abra uma pendência. A resposta precisa ser conferida antes de liberar a demanda.',button:'Ver requisições',page:'requisicoes'},
 {tab:'Programação',hint:'Defina o próximo passo',title:'Organize a sequência de atendimento',body:'Na programação, confira responsável, início previsto, data de atendimento e próxima ação. Em seguida, vincule a referência do processo oficial.',tip:'Mover um cartão pede confirmação e não altera prioridade nem resolve pendências.',button:'Abrir programação',page:'programacao'},
 {tab:'Recebimento',hint:'Confira até concluir',title:'Registre a entrega — mesmo que parcial',body:'Informe o que foi entregue, aceito e rejeitado. O saldo restante continua visível para a equipe até o atendimento integral.',tip:'A requisição só pode ser concluída quando o saldo aprovado estiver atendido.',button:'Ir para recebimentos',page:'recebimentos'}
];
let activeTutorialStep=0;
let tutorialCompleted=sessionStorage.getItem('greenfarm-tutorial-completed')==='true';
function setTutorialStep(index,focus=false){const stepper=document.querySelector('.tutorial-stepper');if(!stepper)return;activeTutorialStep=(index+tutorialSteps.length)%tutorialSteps.length;const step=tutorialSteps[activeTutorialStep];stepper.querySelectorAll('[role="tab"]').forEach((tab,i)=>{const active=i===activeTutorialStep;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;tab.classList.toggle('active',active)});const panel=stepper.querySelector('[role="tabpanel"]');panel.setAttribute('aria-labelledby',`tutorial-tab-${activeTutorialStep}`);panel.innerHTML=`<div class="tutorial-panel-copy"><span class="tutorial-kicker">PASSO ${String(activeTutorialStep+1).padStart(2,'0')} · ${step.tab.toUpperCase()}</span><h3>${step.title}</h3><p>${step.body}</p><div class="tutorial-tip"><span aria-hidden="true">i</span><p>${step.tip}</p></div></div><div class="tutorial-panel-action"><span class="tutorial-action-mark">${String(activeTutorialStep+1).padStart(2,'0')}</span><span class="tutorial-action-caption">PRÓXIMA AÇÃO</span><button class="primary-button" ${step.action?`data-action="${step.action}"`:`data-go="${step.page}"`}>${step.button} <span>↗</span></button></div>`;stepper.querySelector('.tutorial-progress-label').textContent=`Etapa ${activeTutorialStep+1} de ${tutorialSteps.length}`;stepper.querySelector('.tutorial-progress-fill').style.width=`${(activeTutorialStep+1)/tutorialSteps.length*100}%`;const prev=stepper.querySelector('[data-tutorial-prev]');prev.disabled=activeTutorialStep===0;const next=stepper.querySelector('[data-tutorial-next]');next.innerHTML=activeTutorialStep===tutorialSteps.length-1?'Concluir tutorial <span>✓</span>':'Próxima etapa <span>→</span>';if(focus)stepper.querySelector(`[data-tutorial-step="${activeTutorialStep}"]`).focus()}
function setupTutorialStepper(){const old=document.querySelector('.tutorial-section');if(!old)return;old.outerHTML=`<div class="tutorial-onboarding" role="dialog" aria-modal="true" aria-labelledby="tutorial-title"><div class="tutorial-backdrop" aria-hidden="true"></div><section class="tutorial-stepper" id="tutorial" aria-labelledby="tutorial-title"><div class="tutorial-heading"><div><div class="eyebrow">PRIMEIROS PASSOS</div><h2 id="tutorial-title">Como usar a GreenFarm</h2><p>Avance por cada etapa para conhecer o caminho de uma demanda.</p></div><span class="tutorial-duration">GUIA RÁPIDO <i>·</i> 4 ETAPAS</span></div><section class="tutorial-overview" aria-label="Apresentação e funcionalidades da GreenFarm"><div class="tutorial-overview-copy"><span class="eyebrow">CONHEÇA A GREENFARM</span><h3>Da necessidade à entrega, tudo no mesmo fluxo.</h3><p>A GreenFarm ajuda as equipes da Saúde e de Compras a acompanhar cada demanda, entender o que precisa de atenção e saber qual é o próximo passo.</p></div><div class="tutorial-overview-features"><article><span>▤</span><div><strong>Registrar solicitações</strong><p>Informe item, quantidade, necessidade e justificativa da unidade.</p></div></article><article><span>◷</span><div><strong>Priorizar e programar</strong><p>Veja etapas, responsáveis, previsões e pendências em um quadro.</p></div></article><article><span>⌘</span><div><strong>Acompanhar processos</strong><p>Relacione demandas às referências oficiais e acompanhe as subetapas.</p></div></article><article><span>⇣</span><div><strong>Conferir recebimentos</strong><p>Registre entregas parciais, quantidades aceitas e saldo restante.</p></div></article></div><div class="tutorial-overview-notes"><p><strong>Prioridade, etapa e pendência são informações diferentes.</strong> A GreenFarm registra cada uma separadamente e mantém o histórico das decisões.</p><p><strong>A GreenFarm acompanha o processo oficial;</strong> não substitui decisões nem documentos da contratação. Use dados fictícios neste ambiente de demonstração.</p></div></section><div class="tutorial-card"><div class="tutorial-tabs" role="tablist" aria-label="Etapas para acompanhar uma demanda">${tutorialSteps.map((step,i)=>`<button type="button" class="tutorial-tab ${i===activeTutorialStep?'active':''}" role="tab" id="tutorial-tab-${i}" aria-controls="tutorial-panel" aria-selected="${i===activeTutorialStep}" tabindex="${i===activeTutorialStep?0:-1}" data-tutorial-step="${i}"><span class="tutorial-tab-number">0${i+1}</span><span class="tutorial-tab-copy"><strong>${step.tab}</strong><small>${step.hint}</small></span></button>`).join('')}</div><div class="tutorial-panel" id="tutorial-panel" role="tabpanel" tabindex="0" aria-labelledby="tutorial-tab-0"></div><div class="tutorial-card-footer"><div class="tutorial-progress"><span class="tutorial-progress-label">Etapa 1 de ${tutorialSteps.length}</span><span class="tutorial-progress-track"><i class="tutorial-progress-fill"></i></span></div><div class="tutorial-controls"><button type="button" class="tutorial-control" data-tutorial-prev disabled>← <span>Anterior</span></button><button type="button" class="tutorial-control tutorial-control-next" data-tutorial-next>Próxima etapa <span>→</span></button></div></div></div></section></div>`;if(tutorialCompleted)document.querySelector('.tutorial-onboarding').hidden=true;else setTutorialStep(activeTutorialStep)}
function completeTutorial(){tutorialCompleted=true;sessionStorage.setItem('greenfarm-tutorial-completed','true');document.querySelector('.tutorial-onboarding').hidden=true}
function render(){const key=currentPage(),title=pageTitles[key]||pageTitles.inicio;document.getElementById('breadcrumb-current').textContent=title;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===key));const views={inicio:dashboard,requisicoes:requestsPage,programacao:board,processos:processPage,recebimentos:receivesPage,indicadores:analyticsPage,historico:historyPage,cadastros:catalogPage};document.getElementById('page-content').innerHTML=key==='inicio'?homeGuide()+dashboard():(views[key]||dashboard)();if(key==='inicio')setupTutorialStepper();document.getElementById('request-count').textContent=state.requests.filter(r=>r.stage!=='Concluídas').length;bindDynamic();}

function toast(message,error=false){const region=document.getElementById('toast-region'),el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;region.append(el);setTimeout(()=>el.remove(),3400)}
function addHistory(r,text,actor='Equipe GreenFarm'){r.history=r.history||[];r.history.unshift({date:isoDay(0),actor,text});}
function modal(title,subtitle,body,footer='',wide=false){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header"><div><h2>${title}</h2><p>${subtitle||''}</p></div><button class="modal-close" data-close-modal aria-label="Fechar">×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;const focus=document.querySelector('.modal input, .modal select, .modal textarea');focus?.focus();}
const cancelFooter=`<button class="quiet-button" data-close-modal>Cancelar</button><div><button class="primary-button" type="submit" form="modal-form">Confirmar</button></div>`;
function showNewRequest(){modal('Nova requisição','Informe a necessidade para encaminhar à análise.',`<form id="modal-form" class="form-grid"><div class="form-section-title">Identificação</div><div class="field"><label for="request-item">Item solicitado *</label><input id="request-item" name="item" required placeholder="Ex.: Paracetamol 500 mg" /></div><div class="field"><label for="request-unit">Unidade solicitante *</label><select id="request-unit" name="unit"><option>UBS Jardim das Flores</option><option>UBS Centro</option><option>UBS São Patrício</option><option>UBS Vila Nova</option><option>UPA Ceres</option></select></div><div class="field"><label for="request-qty">Quantidade *</label><input id="request-qty" name="qty" type="number" min="1" required placeholder="0" /></div><div class="field"><label>Unidade de medida</label><select name="measure"><option>Unidades</option><option>Caixas</option><option>Frascos</option><option>Comprimidos</option></select></div><div class="form-section-title">Necessidade</div><div class="field"><label for="request-need">Data da necessidade *</label><input id="request-need" name="need" type="date" min="${isoDay(0)}" required value="${isoDay(30)}" /></div><div class="field"><label for="request-impact">Impacto da falta *</label><select name="impact"><option value="">Selecione uma opção</option><option>Risco de interrupção de atendimento</option><option>Redução de cobertura assistencial</option><option>Impacto operacional moderado</option></select></div><div class="field full"><label for="request-summary">Justificativa *</label><textarea id="request-summary" name="summary" required placeholder="Explique a necessidade e as evidências disponíveis"></textarea><small>Dados de estoque não informados não serão tratados como zero.</small></div></form>`,cancelFooter,true);}
function publicId(){const years=state.requests.map(r=>Number(r.id.split('-').at(-1))).filter(Number.isFinite);return `REQ-${today.getFullYear()}-${String(Math.max(0,...years)+1).padStart(4,'0')}`}
function showDetail(id){const r=byId(id);if(!r)return;const actionButtons=[r.pending?'<button class="secondary-button" data-request-action="respond" data-id="'+id+'">Responder pendência</button><button class="secondary-button" data-request-action="resolve" data-id="'+id+'">Resolver pendência</button>':'',r.stage==='Em análise'?'<button class="secondary-button" data-request-action="pending" data-id="'+id+'">Abrir pendência</button><button class="primary-button" data-request-action="approve" data-id="'+id+'">Analisar e aprovar</button>':'',r.stage==='Aprovadas'?'<button class="primary-button" data-request-action="schedule" data-id="'+id+'">Programar demanda</button>':'',r.stage==='Programadas'&&!r.process?'<button class="primary-button" data-request-action="link" data-id="'+id+'">Vincular processo</button>':'',r.stage==='Aguardando entrega'&&remaining(r)>0?'<button class="primary-button" data-receive="'+id+'">Registrar recebimento</button>':''].filter(Boolean).join('');modal(`${r.id} · ${esc(r.item)}`,esc(r.unit),`<div class="detail-hero"><div><div class="detail-id">DEMANDA ${r.id}</div><h3 class="detail-title">${esc(r.item)}</h3><div class="detail-sub">Solicitada por ${esc(r.owner||'Unidade solicitante')}</div></div>${badge(r.stage,stageClass(r.stage))}</div><div style="display:flex;gap:7px;margin-top:11px"><span class="priority-pill ${priorityClass(r.priorityKey)}">${esc(r.priority)}</span>${r.pending?badge('Pendência: '+r.pending,'badge-pending'):badge('Sem pendência aberta','badge-ok')}</div>${tags(r)}<div class="detail-grid"><div class="detail-cell"><small>Quantidade solicitada</small><strong>${r.qty} un.</strong></div><div class="detail-cell"><small>Aprovada</small><strong>${r.approved} un.</strong></div><div class="detail-cell"><small>Aceita</small><strong>${r.accepted} un.</strong></div><div class="detail-cell"><small>Saldo pendente</small><strong>${remaining(r)} un.</strong></div><div class="detail-cell"><small>Data da necessidade</small><strong>${dateLabel(r.need)}</strong></div><div class="detail-cell"><small>Atendimento previsto</small><strong>${dateLabel(r.due)}</strong></div><div class="detail-cell"><small>Responsável atual</small><strong>${esc(r.owner)}</strong></div><div class="detail-cell"><small>Processo oficial</small><strong>${esc(r.process||'Ainda não vinculado')}</strong></div></div><div class="detail-section"><h4>Justificativa e evidências</h4><p>${esc(r.summary||'Ainda não informada.')}</p></div>${r.pendingResponse?`<div class="detail-section"><h4>Resposta à pendência</h4><p>${esc(r.pendingResponse)}</p></div>`:''}<div class="detail-section"><h4>Atividade recente</h4><div class="timeline">${(r.history||[]).slice(0,3).map(h=>`<div class="timeline-item"><span class="timeline-time">${dateLabel(h.date)}</span><span class="timeline-rail"><i class="timeline-dot"></i></span><span class="timeline-copy"><strong>${esc(h.text)}</strong><p>por ${esc(h.actor)}</p></span></div>`).join('')}</div></div>`,`<button class="quiet-button" data-close-modal>Fechar</button><div class="detail-actions">${actionButtons}</div>`,true)}

function showApprove(id){const r=byId(id);if(!r)return;modal('Análise e decisão',`${id} · ${esc(r.item)}`,`<form id="modal-form" class="form-grid"><div class="page-note field full" style="margin:0">Solicitado: ${r.qty} unidades · Necessidade: ${dateLabel(r.need)}. ${esc(r.summary)}</div><div class="field"><label>Decisão *</label><select name="decision"><option value="approve">Aprovar</option><option value="return">Devolver para análise</option><option value="reject">Indeferir</option></select></div><div class="field"><label>Prioridade confirmada *</label><select name="priority"><option>Revisão imediata</option><option>Antecipação necessária</option><option>Planejada</option></select></div><div class="field"><label>Quantidade aprovada *</label><input type="number" name="approved" min="1" max="${r.qty}" value="${r.qty}" required /></div><div class="field"><label>Criticidade XYZ</label><select name="xyz"><option value="Z">Z — Alta criticidade</option><option value="Y">Y — Média criticidade</option><option value="X">X — Baixa criticidade</option></select></div><div class="field full"><label>Parecer e justificativa da decisão *</label><textarea name="reason" required placeholder="Registre a evidência considerada e o motivo"></textarea></div></form>`,cancelFooter,true);document.querySelector('#modal-form').dataset.requestId=id;document.querySelector('#modal-form').dataset.formType='approve'}
function showPending(id){const r=byId(id);modal('Abrir pendência',`${id} · Solicite uma correção específica.`, `<form id="modal-form" class="form-grid"><div class="field full"><label>O que precisa ser complementado? *</label><textarea name="pending" required placeholder="Descreva claramente a informação necessária"></textarea></div><div class="field"><label>Responsável pelo retorno *</label><select name="responsible"><option>Unidade solicitante</option><option>Farmácia central</option><option>Coordenação da Saúde</option></select></div><div class="field"><label>Prazo para resposta *</label><input type="date" name="deadline" value="${isoDay(3)}" required></div></form>`,cancelFooter);document.querySelector('#modal-form').dataset.requestId=id;document.querySelector('#modal-form').dataset.formType='pending'}
function showRespond(id){modal('Responder pendência',`${id} · Registre o complemento enviado pela unidade.`,`<form id="modal-form" class="form-grid"><div class="field full"><label>Resposta e informação complementar *</label><textarea name="response" required placeholder="Descreva a informação ou evidência encaminhada"></textarea></div></form>`,cancelFooter);document.querySelector('#modal-form').dataset.requestId=id;document.querySelector('#modal-form').dataset.formType='respond'}
function showResolve(id){const r=byId(id);if(!r.pendingResponse){toast('A pendência precisa de uma resposta antes da resolução.',true);return}modal('Conferir e resolver pendência',`${id} · Confirme a análise do retorno.`,`<form id="modal-form" class="form-grid"><div class="page-note field full" style="margin:0"><strong>Pendência:</strong> ${esc(r.pending)}<br><br><strong>Resposta:</strong> ${esc(r.pendingResponse)}</div><div class="field full"><label>Decisão *</label><select name="decision"><option value="resolve">Conferido · resolver pendência</option><option value="reopen">Precisa de novo complemento</option></select></div><div class="field full"><label>Observação da análise *</label><textarea name="reason" required placeholder="Registre o resultado da conferência"></textarea></div></form>`,cancelFooter);document.querySelector('#modal-form').dataset.requestId=id;document.querySelector('#modal-form').dataset.formType='resolve'}
function showSchedule(id){const r=byId(id);modal('Programar demanda',`${id} · ${esc(r.item)}`,`<form id="modal-form" class="form-grid"><div class="page-note field full" style="margin:0">Prioridade confirmada: ${esc(r.priority)}. A previsão original de necessidade é ${dateLabel(r.need)}.</div><div class="field"><label>Responsável pela ação *</label><select name="owner"><option>Equipe de Compras</option><option>Equipe de Compras</option><option>Equipe GreenFarm</option></select></div><div class="field"><label>Próxima ação *</label><select name="next"><option>Preparar documentação</option><option>Conferir especificações</option><option>Consolidar demanda</option></select></div><div class="field"><label>Início previsto *</label><input name="start" type="date" value="${isoDay(0)}" required></div><div class="field"><label>Atendimento previsto *</label><input name="due" type="date" value="${isoDay(14)}" required></div><div class="field"><label>Prazo da próxima ação *</label><input name="actionDue" type="date" value="${isoDay(4)}" required></div><div class="field full"><label>Motivo / observação *</label><textarea name="reason" required placeholder="Justifique a previsão e a sequência de atendimento"></textarea></div></form>`,cancelFooter);document.querySelector('#modal-form').dataset.requestId=id;document.querySelector('#modal-form').dataset.formType='schedule'}
function showReceive(id=''){const candidates=state.requests.filter(r=>r.stage==='Aguardando entrega'&&remaining(r)>0);modal('Conferir recebimento','Registre a quantidade entregue e efetivamente aceita.',`<form id="modal-form" class="form-grid"><div class="field full"><label>Requisição *</label><select name="request" required>${candidates.map(r=>`<option value="${r.id}" ${r.id===id?'selected':''}>${r.id} · ${esc(r.item)} · saldo ${remaining(r)} un.</option>`).join('')}</select></div><div class="field"><label>Data da conferência *</label><input type="date" name="date" value="${isoDay(0)}" required></div><div class="field"><label>Quantidade entregue *</label><input type="number" name="delivered" min="1" required placeholder="0"></div><div class="field"><label>Quantidade aceita *</label><input type="number" name="accepted" min="0" required placeholder="0"></div><div class="field"><label>Quantidade rejeitada</label><input type="number" name="rejected" min="0" value="0"></div><div class="field full"><label>Observação da conferência</label><textarea name="reason" placeholder="Descreva divergências, se houver"></textarea></div></form>`,cancelFooter);document.querySelector('#modal-form').dataset.formType='receive'}
function showProcess(){modal('Cadastrar processo','Registre a referência oficial para acompanhamento.',`<form id="modal-form" class="form-grid"><div class="field"><label>Número oficial *</label><input name="number" required placeholder="PROC-2026-016"></div><div class="field"><label>Órgão ou setor *</label><input name="org" required value="Setor de Compras"></div><div class="field"><label>Responsável *</label><input name="owner" required value="Equipe de Compras"></div><div class="field"><label>Subetapa atual *</label><select name="stage"><option>Preparação</option><option>Instrução processual</option><option>Publicação</option><option>Julgamento</option><option>Homologação</option><option>Aguardando entrega</option></select></div><div class="field full"><label>Referência ou link</label><input name="reference" placeholder="URL ou número de referência"></div></form>`,cancelFooter);document.querySelector('#modal-form').dataset.formType='process'}
function showLink(id){const r=byId(id);modal('Vincular processo',`${id} · ${esc(r.item)}`,`<form id="modal-form" class="form-grid"><div class="field full"><label>Processo de compra *</label><select name="process">${state.processes.filter(p=>p.stage!=='Concluído').map(p=>`<option value="${p.id}">${p.id} · ${esc(p.org)} · ${p.stage}</option>`).join('')}</select></div><div class="page-note field full" style="margin:0">Uma requisição pode ter um vínculo de processo ativo por vez. O vínculo mantém a quantidade aprovada registrada.</div></form>`,cancelFooter);document.querySelector('#modal-form').dataset.formType='link';document.querySelector('#modal-form').dataset.requestId=id}
function showMove(id,target){const r=byId(id);if(!r||target===r.stage)return;let body=`<form id="modal-form" class="form-grid"><div class="page-note field full" style="margin:0">Etapa atual: <strong>${r.stage}</strong> → nova etapa solicitada: <strong>${target}</strong>. A prioridade continua ${esc(r.priority)} e não será alterada por esta movimentação.</div>`;if(target==='Programadas')body+=`<div class="field full"><label>Responsável *</label><select name="owner"><option>Equipe de Compras</option><option>Equipe de Compras</option></select></div><div class="field"><label>Atendimento previsto *</label><input type="date" name="due" value="${isoDay(14)}" required></div><div class="field"><label>Próxima ação *</label><input name="next" required placeholder="Ex.: Preparar documentação"></div><div class="field full"><label>Justificativa *</label><textarea name="reason" required></textarea></div>`;else if(target==='Em contratação'&&!r.process)body+=`<div class="field full"><label>Processo de compra *</label><select name="process">${state.processes.map(p=>`<option value="${p.id}">${p.id} · ${p.org}</option>`).join('')}</select></div>`;body+='</form>';modal('Confirmar mudança de etapa',r.id,body,cancelFooter);const f=document.querySelector('#modal-form');f.dataset.formType='move';f.dataset.requestId=id;f.dataset.target=target;}
function priorityValues(text){return text==='Revisão imediata'?['immediate','Revisão imediata']:text==='Antecipação necessária'?['advance','Antecipação necessária']:['planned','Planejada']}

function bindDynamic(){document.querySelectorAll('[data-open]').forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('button'))return;showDetail(el.dataset.open)}));document.querySelectorAll('[data-card]').forEach(card=>{card.addEventListener('dragstart',e=>{card.classList.add('dragging');e.dataTransfer.setData('text/plain',card.dataset.card)});card.addEventListener('dragend',()=>card.classList.remove('dragging'))});document.querySelectorAll('[data-column]').forEach(col=>{col.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drag-over')});col.addEventListener('dragleave',()=>col.classList.remove('drag-over'));col.addEventListener('drop',e=>{e.preventDefault();col.classList.remove('drag-over');const id=e.dataTransfer.getData('text/plain');if(id)showMove(id,col.dataset.column)})});document.querySelector('#request-search')?.addEventListener('input',filterRequests);document.querySelector('#priority-filter')?.addEventListener('change',filterRequests);document.querySelector('#stage-filter')?.addEventListener('change',filterRequests);document.querySelector('#process-search')?.addEventListener('input',e=>document.querySelectorAll('.process-card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(e.target.value.toLowerCase())));document.querySelector('#catalog-search')?.addEventListener('input',e=>document.querySelectorAll('.data-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));document.querySelector('#history-filter')?.addEventListener('change',e=>document.querySelectorAll('.timeline-item[data-history]').forEach(x=>x.hidden=!!e.target.value&&x.dataset.history!==e.target.value));}
function filterRequests(){const q=(document.querySelector('#request-search')?.value||'').toLowerCase(),p=document.querySelector('#priority-filter')?.value||'',s=document.querySelector('#stage-filter')?.value||'';let list=state.requests.filter(r=>(state.tab==='Concluídas'?r.stage==='Concluídas':r.stage!=='Concluídas')&&(!q||`${r.id} ${r.item} ${r.unit}`.toLowerCase().includes(q))&&(!p||r.priority===p)&&(!s||r.stage===s));document.querySelector('#request-table').innerHTML=requestTable(list);document.querySelectorAll('#request-table [data-open]').forEach(el=>el.addEventListener('click',()=>showDetail(el.dataset.open)))}
function navigate(page){state.currentPage=page;save();render();document.querySelector('.sidebar').classList.remove('open');window.scrollTo(0,0)}
function exportCsv(){const rows=[['Número','Item','Unidade','Etapa','Prioridade','Quantidade aprovada','Aceita','Saldo','Previsão'],...state.requests.map(r=>[r.id,r.item,r.unit,r.stage,r.priority,r.approved,r.accepted,remaining(r),r.due])];const csv='\ufeff'+rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='greenfarm-requisicoes.csv';a.click();URL.revokeObjectURL(a.href);toast('Arquivo CSV exportado.');}

document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return}const go=e.target.closest('[data-go]');if(go){navigate(go.dataset.go);return}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;save();render();return}const act=e.target.closest('[data-action]');if(act){({ 'new-request':showNewRequest,'new-process':showProcess,'export':exportCsv,'receive':()=>showReceive(),'new-item':()=>toast('Cadastro de itens estará disponível nesta etapa do piloto.'),'help-button':()=>showHelp()}[act.dataset.action]||(()=>{}))();return}const rec=e.target.closest('[data-receive]');if(rec){showReceive(rec.dataset.receive);return}const reqAction=e.target.closest('[data-request-action]');if(reqAction){const id=reqAction.dataset.id;document.getElementById('modal-root').innerHTML='';if(reqAction.dataset.requestAction==='approve')showApprove(id);if(reqAction.dataset.requestAction==='pending')showPending(id);if(reqAction.dataset.requestAction==='schedule')showSchedule(id);if(reqAction.dataset.requestAction==='link')showLink(id);return}const process=e.target.closest('[data-process]');if(process){const p=state.processes.find(x=>x.id===process.dataset.process);const linked=state.requests.filter(r=>r.process===p.id);modal(`${p.id} · ${esc(p.org)}`,`${esc(p.stage)} · responsável: ${esc(p.owner)}`,`<div class="detail-grid"><div class="detail-cell"><small>Subetapa</small><strong>${esc(p.stage)}</strong></div><div class="detail-cell"><small>Responsável</small><strong>${esc(p.owner)}</strong></div><div class="detail-cell"><small>Demandas vinculadas</small><strong>${linked.length}</strong></div><div class="detail-cell"><small>Quantidade aprovada</small><strong>${linked.reduce((n,r)=>n+r.approved,0)} un.</strong></div></div><div class="detail-section"><h4>Requisições vinculadas</h4>${linked.map(r=>`<p style="padding:7px 0;border-bottom:1px solid #eef1f4"><strong>${r.id}</strong> · ${esc(r.item)} · ${r.approved} un. · ${esc(r.stage)}</p>`).join('')||'<p>Nenhuma requisição vinculada.</p>'}</div>`,`<button class="quiet-button" data-close-modal>Fechar</button><div><button class="primary-button" data-update-process="${p.id}">Atualizar subetapa</button></div>`,true);return}const up=e.target.closest('[data-update-process]');if(up){const id=up.dataset.updateProcess;const p=state.processes.find(x=>x.id===id);modal('Atualizar subetapa',id,`<form id="modal-form" class="form-grid"><div class="field full"><label>Nova subetapa *</label><select name="stage"><option>Preparação</option><option>Instrução processual</option><option>Publicação</option><option>Julgamento</option><option>Homologação</option><option>Aguardando entrega</option></select></div><div class="field full"><label>Ocorrência / próxima ação *</label><textarea name="reason" required></textarea></div></form>`,cancelFooter);const f=document.querySelector('#modal-form');f.dataset.formType='processUpdate';f.dataset.processId=id;return}const close=e.target.closest('[data-close-modal]');if(close){if(e.target===close||close.classList.contains('modal-close'))document.getElementById('modal-root').innerHTML='';return}if(e.target.id==='notification-button'){toggleNotifications();return}if(e.target.closest('#profile-button,#top-profile')){showProfile();return}if(e.target.id==='mobile-menu'){document.querySelector('.sidebar').classList.toggle('open');return}if(e.target.id==='help-button'){showHelp();return}if(e.target.closest('[data-filter]')){const filter=e.target.closest('[data-filter]');document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===filter));document.querySelectorAll('.request-card').forEach(c=>{const r=byId(c.dataset.card);c.hidden=filter.dataset.filter==='priority'?r.priorityKey!=='immediate':filter.dataset.filter==='pending'?!r.pending:false});return}});
function showHelp(){modal('Guia rápido GreenFarm','Uma visão do fluxo de acompanhamento.',`<div class="detail-section" style="border:0;padding:0;margin:0"><h4>Como acompanhar uma demanda</h4><p>1. A unidade registra o item, a quantidade, a necessidade e as evidências.<br><br>2. Farmácia e coordenação analisam os dados, registram parecer e confirmam prioridade.<br><br>3. Compras programa a demanda e vincula o processo oficial.<br><br>4. Recebimentos registra conferências parciais até o atendimento integral.<br><br>5. O histórico preserva as decisões e atualizações.</p><div class="page-note">Etapa, prioridade e pendência são informações independentes. A ferramenta acompanha o processo oficial e não substitui decisões da equipe.</div></div>`,`<button class="primary-button" data-close-modal>Entendi</button>`)}
function showProfile(){modal('Perfil de demonstração','Usuário e papel ativos nesta sessão.',`<div style="display:flex;align-items:center;gap:12px"><span class="avatar avatar-blue" style="width:42px;height:42px">LM</span><span><strong style="font-size:12px">Equipe GreenFarm</strong><br><small style="color:#8493a2">Perfil demonstrativo</small></span></div><div class="page-note">A troca de perfil demonstrativo altera permissões no protótipo completo. Este ambiente usa uma identidade fictícia única e não autentica usuários reais.</div>`,`<button class="primary-button" data-close-modal>Fechar</button>`)}
function toggleNotifications(){const old=document.querySelector('.notification-pop');if(old){old.remove();return}const pending=state.requests.filter(r=>r.pending),receiving=state.requests.filter(r=>r.stage==='Aguardando entrega'&&remaining(r)>0),messages=[...pending.map(r=>`${esc(r.id)} aguarda complemento: ${esc(r.pending)}`),...receiving.map(r=>`${esc(r.id)} tem ${remaining(r)} unidades pendentes de recebimento.`)];const b=document.getElementById('notification-button'),div=document.createElement('div');div.className='notification-pop';div.innerHTML=`<strong>Notificações</strong>${messages.length?messages.map(m=>`<p>${m}</p>`).join(''):'<p>Nenhuma notificação pendente.</p>'}`;b.parentElement.append(div)}

document.addEventListener('submit',e=>{if(e.target.id!=='modal-form')return;e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f).entries()),type=f.dataset.formType,id=f.dataset.requestId;let r=id?byId(id):null;if(type==='approve'){if(r.pending){toast('Resolva a pendência antes de aprovar.',true);return}if(data.decision==='approve'){r.stage='Aprovadas';r.approved=Number(data.approved);[r.priorityKey,r.priority]=priorityValues(data.priority);r.xyz=data.xyz;r.owner='Compras';r.summary=`${r.summary} Parecer: ${data.reason}`;addHistory(r,`Aprovada a quantidade de ${r.approved} unidades; prioridade ${r.priority} confirmada.`)}else if(data.decision==='return'){r.stage='Em análise';addHistory(r,`Devolvida para análise: ${data.reason}`)}else{r.stage='Indeferidas';addHistory(r,`Requisição indeferida: ${data.reason}`)}}else if(type==='pending'){r.pending=data.pending;r.blocked=true;r.owner=data.responsible;addHistory(r,`Pendência aberta: ${data.pending}`)}else if(type==='schedule'){if(data.due<data.start){toast('O atendimento previsto não pode anteceder o início.',true);return}if(data.due>r.need&&!data.reason.trim()){toast('Informe o motivo da previsão após a necessidade.',true);return}r.stage='Programadas';r.owner=data.owner;r.start=data.start;r.due=data.due;r.next=data.next;r.actionDue=data.actionDue;r.scheduleReason=data.reason;addHistory(r,`Programada para ${dateLabel(data.due)}; próxima ação: ${data.next}.`)}else if(type==='receive'){const item=byId(data.request),del=Number(data.delivered),acc=Number(data.accepted),rej=Number(data.rejected||0);if(!item||del>remaining(item)||acc+rej>del||acc<0){toast('Confira as quantidades. A entrega não pode exceder o saldo pendente.',true);return}item.accepted+=acc;addHistory(item,`Recebimento conferido: ${acc} aceitas e ${rej} rejeitadas (${dateLabel(data.date)}).`,'Equipe de Recebimento');if(remaining(item)===0){item.stage='Concluídas';addHistory(item,'Demanda concluída após atendimento integral.','Equipe de Recebimento')}toast(`Recebimento registrado. Saldo pendente: ${remaining(item)} un.`);document.getElementById('modal-root').innerHTML='';save();render();return}else if(type==='process'){const processId=data.number.trim();if(state.processes.some(p=>p.id.toLowerCase()===processId.toLowerCase())){toast('Já existe um processo com esse número.',true);return}state.processes.unshift({id:processId,org:data.org,stage:data.stage,owner:data.owner,count:0});toast('Processo cadastrado.');document.getElementById('modal-root').innerHTML='';save();render();return}else if(type==='link'){if(!data.process){toast('Cadastre um processo antes de vincular.',true);return}r.process=data.process;r.stage='Em contratação';const p=state.processes.find(x=>x.id===data.process);if(p)p.count=(p.count||0)+1;addHistory(r,`Vinculada ao processo ${data.process}.`);toast('Vínculo de processo registrado.');document.getElementById('modal-root').innerHTML='';save();render();return}else if(type==='move'){const target=f.dataset.target;if(r.blocked&&target!=='Em análise'){toast('Resolva a pendência bloqueante antes de avançar.',true);return}if(target==='Programadas'){r.owner=data.owner;r.due=data.due;r.next=data.next;r.scheduleReason=data.reason}if(target==='Em contratação'&&data.process){r.process=data.process}r.stage=target;addHistory(r,`Etapa alterada para ${target}.`);toast(`Demanda movida para ${target}.`)}else if(type==='processUpdate'){const p=state.processes.find(x=>x.id===f.dataset.processId);p.stage=data.stage;p.note=data.reason;state.requests.filter(x=>x.process===p.id).forEach(x=>{if(data.stage==='Aguardando entrega')x.stage='Aguardando entrega';addHistory(x,`Processo ${p.id}: ${data.stage}. ${data.reason}`)});toast('Subetapa e histórico atualizados.');document.getElementById('modal-root').innerHTML='';save();render();return}else{const req={id:publicId(),item:data.item.trim(),unit:data.unit,qty:Number(data.qty),approved:Number(data.qty),accepted:0,stage:'Em análise',priority:'A confirmar',priorityKey:'unknown',abc:'',xyz:'',owner:'Farmácia central',need:data.need,due:'',created:isoDay(0),pending:'',summary:`${data.summary} Impacto: ${data.impact}.`,history:[{date:isoDay(0),actor:'Equipe GreenFarm',text:'Requisição enviada para análise'}]};state.requests.unshift(req);toast(`Requisição ${req.id} enviada para análise.`);document.getElementById('modal-root').innerHTML='';navigate('requisicoes');return}toast('Alterações salvas e histórico atualizado.');document.getElementById('modal-root').innerHTML='';save();render()});

document.getElementById('global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.trim().toLowerCase();if(!q)return;navigate('requisicoes');const input=document.querySelector('#request-search');if(input){input.value=q;filterRequests()}}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('modal-root').innerHTML='';document.querySelector('.notification-pop')?.remove()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('global-search').focus()}});
if(location.protocol==='http:'||location.protocol==='https:'){fetch('/api/state').then(r=>{if(!r.ok)throw Error('api');return r.json()}).then(data=>{if(data.state){state=data.state;localStorage.setItem(STORE_KEY,JSON.stringify(state))}else save();render()}).catch(()=>{render();toast('Modo local ativo: servidor indisponível.',true)})}else render();
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='modal-form'||f.dataset.formType)return;const d=Object.fromEntries(new FormData(f).entries());if(!d.impact){e.preventDefault();e.stopImmediatePropagation();toast('Selecione o impacto da falta para enviar a requisição.',true)}},true);
document.addEventListener('click',e=>{const a=e.target.closest('[data-request-action]');if(!a||!['respond','resolve'].includes(a.dataset.requestAction))return;e.preventDefault();e.stopImmediatePropagation();document.getElementById('modal-root').innerHTML='';if(a.dataset.requestAction==='respond')showRespond(a.dataset.id);else showResolve(a.dataset.id)},true);
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='modal-form'||!['respond','resolve'].includes(f.dataset.formType))return;e.preventDefault();e.stopImmediatePropagation();const r=byId(f.dataset.requestId),d=Object.fromEntries(new FormData(f).entries());if(f.dataset.formType==='respond'){r.pendingResponse=d.response;addHistory(r,'Unidade enviou resposta à pendência.','Unidade solicitante');toast('Resposta registrada; aguardando conferência do analista.')}else if(d.decision==='resolve'){r.pending='';r.blocked=false;r.owner='Farmácia central';addHistory(r,`Pendência conferida e resolvida: ${d.reason}.`,'Farmácia central');toast('Pendência resolvida.')}else{r.pendingResponse='';addHistory(r,`Complemento solicitado novamente: ${d.reason}.`,'Farmácia central');toast('Pendência reaberta para complemento.')}document.getElementById('modal-root').innerHTML='';save();render()},true);
document.addEventListener('click',e=>{const open=e.target.closest('[data-tutorial-open]');if(!open)return;e.preventDefault();document.querySelector('.tutorial-onboarding').hidden=false;setTutorialStep(0)},true);
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tutorial-step]'),prev=e.target.closest('[data-tutorial-prev]'),next=e.target.closest('[data-tutorial-next]');if(!tab&&!prev&&!next)return;e.preventDefault();e.stopImmediatePropagation();if(tab)setTutorialStep(Number(tab.dataset.tutorialStep));else if(prev)setTutorialStep(activeTutorialStep-1);else if(activeTutorialStep===tutorialSteps.length-1)completeTutorial();else setTutorialStep(activeTutorialStep+1)},true);
document.addEventListener('keydown',e=>{if(!e.target.matches('.tutorial-tab[role="tab"]'))return;let next=activeTutorialStep;if(e.key==='ArrowRight')next=(activeTutorialStep+1)%tutorialSteps.length;else if(e.key==='ArrowLeft')next=(activeTutorialStep+tutorialSteps.length-1)%tutorialSteps.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tutorialSteps.length-1;else return;e.preventDefault();setTutorialStep(next,true)},true);